while (isActive) {
    val latestAnimations =
        avatarController.availableAnimations
            .map { animationName -> animationName.trim() }
            .filter { animationName -> animationName.isNotBlank() }
            .distinct()

    if (latestAnimations != availableAnimations) {
        availableAnimations = latestAnimations
    }

    delay(300)
}

fun updateScale(scale: Float) {
    val currentConfig = _uiState.value.config ?: return
    val avatarId = _uiState.value.currentAvatarConfig?.id ?: return
    val updatedConfig = currentConfig.copy(scale = scale)
    viewModelScope.launch { repository.updateAvatarSettings(avatarId, updatedConfig) }
}
// AvatarRepository.updateAvatarSettings:
fun updateAvatarSettings(avatarId: String, newSettings: AvatarInstanceSettings) {
    val updatedSettings = _instanceSettings.value.toMutableMap()
    updatedSettings[avatarId] = newSettings
    _instanceSettings.value = updatedSettings
    saveInstanceSettingsToPrefs(updatedSettings)
}
private fun saveInstanceSettingsToPrefs(settings: Map<String, AvatarInstanceSettings>) {
    val json = gson.toJson(settings)
    prefs.edit { putString(KEY_INSTANCE_SETTINGS, json) }
}
